constexpr int ti[6]={0,0,0,1,1,2},tj[6]={0,1,2,1,2,2};
std::array<Real,13> Pole(const h::Z4cJet<Real>&u,const Real*x,bool wormhole){const Real ref[3]={-x[0],-x[1],-x[2]};auto p=h::TensorPoleSources(u,h::CompositeOmegaAt(x,u,true),Real(1),ref,Real(4),Real(-.99),Real(1),Real(1),true,wormhole);std::array<Real,13> out{p.geometry.chi,p.geometry.trace,p.geometry.theta,p.lapse};for(int t=0;t<6;++t)out[4+t]=p.geometry.a[ti[t]][tj[t]];for(int i=0;i<3;++i)out[10+i]=p.geometry.lambda[i];return out;}
int main(int argc,char**argv){Kokkos::initialize(argc,argv);int code=0;try{
 if(argc!=4)throw std::runtime_error("checkpoint source_tag output.csv");const auto snap=c::CompositeCheckpoint::Read(argv[1],argv[2]);if(snap.step!=2||snap.boundary_derivative_scheme!=1||snap.scri_radial_points!=7)throw std::runtime_error("expected final accepted step2 Hermite7 capture");
 h::CompositeTensorEvolution engine(snap.mesh,snap.telegraph,snap.tolerance,snap.spatial_order,true,snap.wormhole_chart,snap.isotropic_reference,7,snap.radial_interface_stencils,snap.positive_storage,snap.telegraph_width,snap.enriched_log_derivatives,snap.radial_line_smoothing,snap.topology_coarsening,snap.log_halo_enrichment,snap.log_halo_radius,snap.puncture_derivative_scheme,1);engine.state=snap.fields;engine.beta_delta=snap.shift_warm_start;engine.scri->values=snap.boundary_fields;const auto &g=engine.shift.grid;if(g.active.size()>50000)throw std::runtime_error("bounded50000");const auto padded=engine.Padded(engine.state);engine.GeometryJets(engine.state,padded);const auto boundary=engine.Boundary(padded);
 V source(3*g.active.size());for(size_t p=0;p<engine.jets.size();++p){Real rhs[3],reference[3];h::EllipticShiftSource(engine.jets[p],engine.shift.geometry[p],Real(0),rhs);h::ApplyEllipticShift(engine.jets[p].metric,engine.shift.geometry[p],engine.jets[p].beta,reference);for(int v=0;v<3;++v)source[3*p+v]=rhs[v]-reference[v];}
 V applied,residual(source.size());engine.shift.Apply(engine.beta_delta,applied,boundary);Real residual_max=0,conformal=0,volume=0;for(size_t p=0;p<g.active.size();++p){volume+=engine.shift.conformal_volume[p];for(int v=0;v<3;++v){const size_t i=3*p+v;residual[i]=-source[i]-applied[i];residual_max=std::max(residual_max,std::abs(residual[i]));conformal+=engine.shift.conformal_volume[p]*residual[i]*residual[i];}}
 V beta_padded(3*g.count,0),beta_boundary(3*engine.scri->rows.size());for(size_t p=0;p<g.active.size();++p)for(int v=0;v<3;++v)beta_padded[v*g.count+g.active[p]]=engine.beta_delta[3*p+v];g.Fill(beta_padded,3,[&](int v,const std::array<Real,3>&x){return boundary(x)[v];});for(size_t p=0;p<engine.scri->rows.size();++p){const auto &x=engine.scri->rows[p].geometry.x;const auto b=boundary({x[0],x[1],x[2]});for(int v=0;v<3;++v)beta_boundary[3*p+v]=b[v];}
 std::ofstream out(argv[3]);out<<std::setprecision(17)<<"nodes,row,face,j,k,x,y,z,qchi_G,qchi_H,qalpha_G,qalpha_H,Khat_G,Theta_G,Khat_value,Theta_value";const char*names[]={"chi","Khat","Theta","alpha","Axx","Axy","Axz","Ayy","Ayz","Azz","LambdaX","LambdaY","LambdaZ"};for(auto name:names)out<<','<<name;for(int t=0;t<6;++t)for(auto term:{"baseline","chi_normal","chi_tangent","metric_normal","metric_tangent","independent_lambda","curvature","sum_error"})out<<','<<names[4+t]<<'_'<<term;for(auto term:{"metric_normal","metric_tangent","independent_lambda","trace_normal","trace_tangent","curvature","sum_error","Khat_normal","Theta_normal"})for(int i=0;i<3;++i)out<<",Lambda"<<i<<'_'<<term;out<<'\n';
 std::cout<<std::setprecision(17)<<"{\"time\":"<<snap.dt*snap.step<<",\"cells\":"<<g.active.size()<<",\"saved_beta_role\":\"finalaccepted_fresh_solve_IO_capture\",\"saved_beta_original_physical_rms\":"<<std::sqrt(engine.shift.Dot(residual,residual))<<",\"saved_beta_original_conformal_rms\":"<<std::sqrt(conformal/volume)<<",\"saved_beta_original_point_max\":"<<residual_max<<",\"sampler_node_count\":7,\"methods\":[";
 Real helper_error=0,reconstruction=0;bool first_method=true;
 for(int nodes:{7}){if(!first_method)std::cout<<',';first_method=false;try{c::ScriSurface surface(g,22,nodes);surface.values=snap.boundary_fields;surface.beta=beta_boundary;c::HermiteBoundarySampler sampler(surface);const auto fields=sampler.Prepare(padded,surface.values,22,1),beta=sampler.Prepare(beta_padded,surface.beta,3,1);Real largest=0,clock=0,null=0,tangent=0;size_t at=0;int component=0;
 for(size_t p=0;p<surface.rows.size();++p){const auto &row=surface.rows[p];const auto &x=row.geometry.x;const auto sample=sampler.Sample(p,fields),shift=sampler.Sample(p,beta);auto u=h::UnpackComposite(x,sample.value,sample.d,sample.dd,snap.wormhole_chart,snap.isotropic_reference,snap.positive_storage);for(int i=0;i<3;++i){u.beta.value[i]+=shift.value[i];for(int a=0;a<3;++a){u.beta.d[a][i]+=shift.d[i][a];for(int b=0;b<3;++b)u.beta.dd[a][b][i]+=shift.dd[i][a][b];}}auto original=Pole(u,x,snap.wormhole_chart);const auto parts=h::ConformalRHS(u,h::CompositeOmegaAt(x,u,true),Real(4),Real(-.99),true);for(int t=0;t<6;++t)helper_error=std::max(helper_error,std::abs(original[4+t]-parts.pole.a[ti[t]][tj[t]]));
 out<<nodes<<','<<p<<','<<g.mesh.blocks[row.block].face<<','<<row.j<<','<<row.k<<','<<x[0]<<','<<x[1]<<','<<x[2]<<','<<fields.radial_first()[22*p]<<','<<fields.radial_second()[22*p]<<','<<fields.radial_first()[22*p+18]<<','<<fields.radial_second()[22*p+18]<<','<<fields.radial_first()[22*p+13]<<','<<fields.radial_first()[22*p+14]<<','<<u.trace.value<<','<<u.theta.value;for(int f=0;f<13;++f){out<<','<<original[f];if(std::abs(original[f])>largest){largest=std::abs(original[f]);at=p;component=f;}}
 Real dn=0;for(int a=0;a<3;++a)dn+=x[a]*u.chi.d[a];auto base=u;for(int i=0;i<3;++i){base.chi.d[i]=0;base.lambda.value[i]=0;for(int j=0;j<3;++j){base.a.k[i][j]=0;for(int a=0;a<3;++a)base.metric.dg[a][i][j]=0;}}std::array<Real,13> pieces[8];pieces[0]=Pole(base,x,snap.wormhole_chart);for(int mode=1;mode<=6;++mode){auto v=base;if(mode<=2)for(int a=0;a<3;++a)v.chi.d[a]=mode==1?x[a]*dn:u.chi.d[a]-x[a]*dn;if(mode==3||mode==4)for(int i=0;i<3;++i)for(int j=0;j<3;++j){Real d=0;for(int a=0;a<3;++a)d+=x[a]*u.metric.dg[a][i][j];for(int a=0;a<3;++a)v.metric.dg[a][i][j]=mode==3?x[a]*d:u.metric.dg[a][i][j]-x[a]*d;}if(mode==5)for(int i=0;i<3;++i)v.lambda.value[i]=u.lambda.value[i];if(mode==6)for(int i=0;i<3;++i)for(int j=0;j<3;++j)v.a.k[i][j]=u.a.k[i][j];pieces[mode]=Pole(v,x,snap.wormhole_chart);for(int f=0;f<13;++f)pieces[mode][f]-=pieces[0][f];}for(int t=0;t<6;++t){Real sum=0;for(int mode=0;mode<7;++mode){out<<','<<pieces[mode][4+t];sum+=pieces[mode][4+t];}out<<','<<sum-original[4+t];reconstruction=std::max(reconstruction,std::abs(sum-original[4+t]));}
 auto radial_metric=u.metric;for(int i=0;i<3;++i)for(int j=0;j<3;++j){Real d=0;for(int a=0;a<3;++a)d+=x[a]*u.metric.dg[a][i][j];for(int a=0;a<3;++a)radial_metric.dg[a][i][j]=x[a]*d;}const auto geo=h::Geometry(u.metric),radial_geo=h::Geometry(radial_metric);Real terms[9][3]{};const Real factor=u.alpha.value*(4./3*(u.trace.value+2*u.theta.value)+8);Real tn=0,kn=0,thn=0;for(int j=0;j<3;++j){tn+=x[j]*(2*u.trace.d[j]+u.theta.d[j]);kn+=x[j]*u.trace.d[j];thn+=x[j]*u.theta.d[j];}for(int i=0;i<3;++i){terms[0][i]=.5*factor*radial_geo.contracted[i];terms[1][i]=.5*factor*(geo.contracted[i]-radial_geo.contracted[i]);terms[2][i]=-.5*factor*u.lambda.value[i];for(int j=0;j<3;++j){terms[3][i]-=2./3*u.alpha.value*geo.inverse[i][j]*x[j]*tn;terms[7][i]-=4./3*u.alpha.value*geo.inverse[i][j]*x[j]*kn;terms[8][i]-=2./3*u.alpha.value*geo.inverse[i][j]*x[j]*thn;terms[4][i]-=2./3*u.alpha.value*geo.inverse[i][j]*(2*u.trace.d[j]+u.theta.d[j]-x[j]*tn);for(int a=0;a<3;++a)for(int b=0;b<3;++b)terms[5][i]+=4*u.alpha.value*geo.inverse[i][a]*geo.inverse[j][b]*u.a.k[a][b]*x[j];}Real sum=0;for(int t=0;t<6;++t)sum+=terms[t][i];terms[6][i]=sum-original[10+i];reconstruction=std::max(reconstruction,std::abs(terms[6][i]));}for(auto &term:terms)for(Real v:term)out<<','<<v;out<<'\n';Real bn=0,ng=0;for(int i=0;i<3;++i){bn+=u.beta.value[i]*x[i];for(int j=0;j<3;++j)ng+=u.chi.value*geo.inverse[i][j]*x[i]*x[j];}clock=std::max(clock,std::abs(u.alpha.value-1));null=std::max(null,std::abs(bn+u.alpha.value*std::sqrt(ng)));for(int i=0;i<3;++i)tangent=std::max(tangent,std::abs(u.beta.value[i]-bn*x[i]));
 }
 const auto &r=surface.rows[at];auto d=sampler.diagnostics();std::cout<<"{\"nodes\":"<<nodes<<",\"supported\":true,\"pole_max\":"<<largest<<",\"row\":"<<at<<",\"component\":\""<<names[component]<<"\",\"face\":"<<g.mesh.blocks[r.block].face<<",\"j\":"<<r.j<<",\"k\":"<<r.k<<",\"xyz\":["<<r.geometry.x[0]<<','<<r.geometry.x[1]<<','<<r.geometry.x[2]<<"],\"clock\":"<<clock<<",\"null\":"<<null<<",\"tangent\":"<<tangent<<",\"factor_condition\":"<<d.factor_condition_indicator<<",\"value_l1\":"<<d.value_weight_l1<<",\"reproduction\":"<<d.polynomial_reproduction<<'}';
 }catch(const std::exception&e){std::cout<<"{\"nodes\":"<<nodes<<",\"supported\":false,\"reason\":\""<<e.what()<<"\"}";}}
 const bool unchanged=engine.state==snap.fields&&engine.beta_delta==snap.shift_warm_start&&engine.scri->values==snap.boundary_fields;std::cout<<"],\"helper_full_tensor_agreement\":"<<helper_error<<",\"decomposition_error\":"<<reconstruction<<",\"frozen_data_unchanged\":"<<unchanged<<",\"no_solve_or_evolution\":true}\n";if(!unchanged||helper_error>1e-12||reconstruction>1e-12)throw std::runtime_error("frozen diagnostic consistency failed");
 }catch(const std::exception&e){std::cerr<<e.what()<<'\n';code=2;}Kokkos::finalize();return code;}
